create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz default now());
create table if not exists public.vendors(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,vendor_code text not null,vendor_name text not null,created_at timestamptz default now(),unique(user_id,vendor_code));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_code text not null,product_name text not null,price numeric(14,2) not null default 0,discount_1 numeric(5,2),discount_2 numeric(5,2),discount_3 numeric(5,2),discount_4 numeric(5,2),order_conditions text,vendor_items text,last_price_updated_at date default current_date,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,product_code));
create table if not exists public.price_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,request_date date not null,requester text not null,source text,details text not null,status text not null default 'pending' check(status in ('pending','in_progress','done')),vendor_id uuid references public.vendors(id),notes text,status_changed_at timestamptz default now(),created_at timestamptz default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entity_type text not null,entity_id uuid,action text not null,old_data jsonb,new_data jsonb,created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.vendors enable row level security; alter table public.products enable row level security; alter table public.price_requests enable row level security; alter table public.audit_logs enable row level security; alter table public.notifications enable row level security;
create policy "own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own vendors" on public.vendors for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own products" on public.products for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own requests" on public.price_requests for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own audits" on public.audit_logs for select using(auth.uid()=user_id);
create policy "own notifications" on public.notifications for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
